import { Minimatch } from "minimatch";

import { logVerbose } from "./logVerbose";
import { trailingSlash } from "./regex";
import { getUrlPrefix } from "./storage";

export const buildUrl = async (
  url: string,
  searchParams: Record<string, string>,
): Promise<URL> => {
  logVerbose("buildUrl", url, searchParams);
  const urlPrefix = await getUrlPrefix();
  const result = new URL(url, urlPrefix);
  Object.keys(searchParams).forEach((key) => {
    result.searchParams.set(key, decodeURIComponent(searchParams[key]));
  });
  logVerbose("buildUrl", result);
  return result;
};

export const reloadContentScriptUrls = async (
  defaultManifest?: chrome.runtime.ManifestV3,
): Promise<void> => {
  const manifest = defaultManifest ?? chrome.runtime.getManifest();
  const patterns: string[] | undefined = manifest.content_scripts?.reduce(
    (prev, next) => {
      prev.push(...(next.matches ?? []));
      return prev;
    },
    [] as string[],
  );
  if (patterns === undefined) return;
  const tabIdsPromises = patterns
    ?.filter((url) => url !== "<all_urls>")
    .map((url) => chrome.tabs.query({ url, discarded: false }));
  const tabsArray = await Promise.all(tabIdsPromises);
  const tabIds = tabsArray
    .flat()
    .map((tab) => tab?.id)
    .filter((id) => id !== undefined && id !== chrome.tabs.TAB_ID_NONE);
  const distinctTabIds = [...new Set(tabIds)];
  distinctTabIds.forEach((tabId) => {
    if (tabId == null) return;
    chrome.tabs.reload(tabId, { bypassCache: true });
  });
};

export const isEquivalentIAUrl = (current: URL, target: URL): boolean => {
  const isOriginAndPathEqual =
    current.origin === target.origin &&
    current.pathname.replace(trailingSlash, "") ===
      target.pathname.replace(trailingSlash, "");

  if (!isOriginAndPathEqual) {
    return false;
  }

  const unCheckedCurrentSearchParams = new Set(current.searchParams.keys());
  const strictCheckSearchParams = new Set(["isInPersonInterview"]);

  return (
    // Check that all target search params are the same in current
    Array.from(target.searchParams.entries()).every(([key, value]) => {
      unCheckedCurrentSearchParams.delete(key);
      return current.searchParams.get(key) === value;
    }) &&
    // Check that any remaining search params in current are not in the blacklist
    Array.from(unCheckedCurrentSearchParams).every(
      (key) => !strictCheckSearchParams.has(key),
    )
  );
};

export type UrlMappings = {
  matches: string[];
  excludes: string[];
};

export const checkUrlMatches = (
  url: string,
  mappings: UrlMappings,
): boolean => {
  const { matches, excludes } = mappings;

  if (excludes.some((pattern) => new Minimatch(pattern).match(url))) {
    return false;
  }

  if (matches.some((pattern) => new Minimatch(pattern).match(url))) {
    return true;
  }

  return false;
};

type Flatten<T> = T extends infer O ? { [K in keyof O]: O[K] } : never;

type ExtractParam<Path, NextPart> = Path extends `<${infer Param}>`
  ? Record<Param, string> & NextPart
  : NextPart;

type ExtractParams<Path> = Flatten<
  Path extends `${infer Segment}/${infer Rest}`
    ? ExtractParam<Segment, ExtractParams<Rest>>
    : ExtractParam<Path, object>
>;

export const matchPath = <TPath extends string>(
  pattern: TPath,
  url: string,
): ExtractParams<TPath> | null => {
  const regexPattern = `^${pattern
    .replace(/<(\w+)>/g, (_, paramName) => `(?<${paramName}>[^/]+)`)
    .replaceAll("*", ".+")}$`;
  const regex = new RegExp(regexPattern);
  const match = regex.exec(url);
  return match?.groups ? ({ ...match.groups } as ExtractParams<TPath>) : null;
};
