import { featureFlagEnabled, planEnabled } from "../featureFlag";
import { addMessageListener, sendGAEvent } from "../message";
import { initModal, showModal } from "../modal";
import { initSentry } from "../sentry";
import type { AtsParam, ImportMessageListener } from "./types";

type ImportInterviewQuestionsPayload = {
  questions: NonNullable<NonNullable<Message["payload"]>["planQuestions"]>;
  title?: string;
};

type InitInterviewQuestionsImportReturn = {
  featureEnabledPromise: Promise<boolean>;
  initModal(): void;
  showModal(): void;
  addListeners(
    params: ImportMessageListener<ImportInterviewQuestionsPayload>,
  ): void;
};

/**
 * Methods for setting up import interview questions that are common across ATSs
 */
export const initInterviewQuestionsImport = ({
  ats,
}: AtsParam): InitInterviewQuestionsImportReturn => {
  initSentry();

  return {
    featureEnabledPromise: Promise.all([
      featureFlagEnabled("plan:browser-extension:questions:disabled"),
      planEnabled(),
    ]).then(([flagDisabled, planEnabled]) => planEnabled && !flagDisabled),

    initModal: () => {
      initModal({
        path: "/plan/select-plan",
        urlParams: { intent: "interview-questions" },
      });
    },

    showModal: () => {
      showModal();
      sendGAEvent({
        action: "Show modal",
        eventCategory: "interview_plan",
        eventLabel: "Interview questions",
        value: ats,
      });
    },

    addListeners: ({ onImport, onOtherMessage }) => {
      addMessageListener(({ message }) => {
        if (message.action !== "hideModal") {
          onOtherMessage?.(message);
          return;
        }

        if (!message.payload?.planQuestions) return;

        onImport({
          questions: message.payload.planQuestions,
          title: message.payload.text,
        });

        // `ats` is sent back to the main app iframe for use in a GA event
        return { ats };
      });
    },
  };
};
