/**
 * Adds a button next to feedback forms on Lever that will
 * open the plan modal on click and fill the feedback form
 * with BH questions after making a selection from the modal
 */
import { createButton } from "../../utils/button";
import { MutationSummary } from "../../utils/MutationSummary";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { initInterviewQuestionsImport } from "../../utils/plan";
import { waitForHydration } from "./utils";

let sidepanel: HTMLElement | null = null;
let importQuestionsButton: HTMLButtonElement;

const { featureEnabledPromise, initModal, showModal, addListeners } =
  initInterviewQuestionsImport({ ats: "Lever" });

const query = <T extends Element = HTMLElement>(selector: string) =>
  (sidepanel ?? document).querySelector<T>(selector);

const queryAll = <T extends Element = HTMLElement>(selector: string) =>
  (sidepanel ?? document).querySelectorAll<T>(selector);

const addButton = (parent: HTMLElement): void => {
  importQuestionsButton = createButton({
    parent,
    insertBtn(btn) {
      parent.insertBefore(btn, parent.firstElementChild);
    },
    text: "Import form",
    onClick: () => {
      showModal();
    },
    cssClass: ["bh-shine"],
    style: {
      marginTop: "4px",
      marginRight: "12px",
      alignSelf: "start",
    },
  });
};

/** Main entry point */
const setup = async (): Promise<void> => {
  if (!sidepanel) {
    sidepanel = query(".settings-flyover");
    if (!sidepanel) return;
  }

  initModal();

  await waitForHydration(sidepanel);

  const header = query(".template-buttons");
  if (!header?.firstElementChild) return;

  addButton(header.firstElementChild as HTMLElement);
};

onDocumentLoaded(async () => {
  const featureEnabled = await featureEnabledPromise;
  if (!featureEnabled) return;

  setup();

  new MutationSummary({
    queries: [{ element: ".settings-flyover" }],
    callback: ([{ added }]) => {
      if (added.length === 0) return;
      sidepanel = added[0] as HTMLElement;
      setup();
    },
  });
});

/**
 * Sets an input element's value and triggers an event to ensure the page
 * picks up the change.
 * - Simply setting `input.value` does not persist changes on saving
 * - There are no forms on the page, and the inputs don't have any
 * event listeners.
 * - It looks like the root `document` has an event listener for
 *    `"input"` events, and that's what is used to pickup changes.
 */
const fillEl = (el: HTMLInputElement, text: string): void => {
  el.value = text;
  el.dispatchEvent(
    new InputEvent("input", { data: text, inputType: "insertText" }),
  );
};

type AddQuestionParams = {
  text: string;
  addQuestionButton: HTMLElement;
};

/**
 * Adds the question to the last input in the list if it is empty. If the last
 * input is not empty, this will append a new input to the list and fill it.
 */
const addQuestion = ({ text, addQuestionButton }: AddQuestionParams): void => {
  let lastField = [
    ...queryAll<HTMLInputElement>(".card-template-editor-field .classic-input"),
  ].at(-1);
  if (lastField?.value) {
    addQuestionButton.click();
    lastField = [
      ...queryAll<HTMLInputElement>(
        ".card-template-editor-field .classic-input",
      ),
    ].at(-1);
  }

  if (!lastField) return;

  fillEl(lastField, text);
};

addListeners({
  onImport: ({ questions, title }) => {
    const addQuestionButton = query(".new-field button");
    if (!addQuestionButton) return;
    questions.forEach(({ text }) => {
      if (!text) return;
      addQuestion({ text, addQuestionButton });
    });
    importQuestionsButton.classList.remove("bh-shine");

    const titleInput = query<HTMLInputElement>(".template-title");
    if (titleInput && !titleInput.value && title) {
      fillEl(titleInput, title);
    }
  },
});
